     "summary": "9月21日，妙可蓝多发布公告称，董事会于 2026年9月20日收到柴琇提交的辞职报告。柴琇在辞职报告里表明：“为支持公司稳健经营和长远发展，本人申请辞去公司第十二届非独立董事及董事会专门委员会的相关职务”。辞职后，柴琇不再担任妙可蓝多及子公司任何职务。妙可蓝多董事会表示，柴琇辞职不会导致公司董事会成员人数低于法定最低人数，辞职申请自送达公司董事会之日起生效。（文章来源：北京商报）",
