     "ts": 1789998725,
     "summary": "本报讯 （记者梁傲男）近日，科信食品与健康信息交流中心联合科普中国、微博健康发布“十个没想到”，围绕公众关心的饮食营养话题，带来多位食品营养和医学领域专家的权威解读。没想到：配料表并不是越短越好国家食品安全风险评估中心总顾问陈君石说，配料表的长短取决于食品的种类和企业对产品的设计，与产品的安全性和营养没有必然联系。所以，建议大家不要盲目追求“配料表短”，更应关注食品的营养属性。...",
